<?php
namespace Tests\Unit;
use PHPUnit\Framework\TestCase;
class Erp412TraceabilityTest extends TestCase
{
 const PREFIX='TEST-412-';protected $s;protected $lots=array();protected $movements=array();protected $items=array();protected $orders=array();
 protected function setUp():void{try{\DB::select('id')->from('erp_412_lots')->limit(1)->execute();}catch(\Throwable $e){$this->markTestSkipped('Выполните миграции erp412');return;}$this->s=\Service_Erp412_Traceability::instance();}
 protected function tearDown():void{if(!$this->s)return;try{$uuids=$this->lots?\DB::select('uuid')->from('erp_412_lots')->where('id','IN',$this->lots)->execute()->as_array(NULL,'uuid'):array();if($uuids)\DB::delete('erp_208_outbox')->where('aggregate_type','=','lot')->where('aggregate_id','IN',$uuids)->execute();if($this->lots){\DB::delete('erp_412_quality_links')->where('lot_id','IN',$this->lots)->execute();\DB::query(\Database::UPDATE,'ALTER TABLE erp_412_genealogy DISABLE TRIGGER erp_412_genealogy_immutable_trg')->execute();\DB::query(\Database::UPDATE,'ALTER TABLE erp_412_allocations DISABLE TRIGGER erp_412_allocations_immutable_trg')->execute();\DB::delete('erp_412_genealogy')->where('input_lot_id','IN',$this->lots)->or_where('output_lot_id','IN',$this->lots)->execute();\DB::delete('erp_412_allocations')->where('lot_id','IN',$this->lots)->execute();\DB::query(\Database::UPDATE,'ALTER TABLE erp_412_genealogy ENABLE TRIGGER erp_412_genealogy_immutable_trg')->execute();\DB::query(\Database::UPDATE,'ALTER TABLE erp_412_allocations ENABLE TRIGGER erp_412_allocations_immutable_trg')->execute();\DB::query(\Database::UPDATE,'ALTER TABLE erp_412_events DISABLE TRIGGER erp_412_events_immutable_trg')->execute();\DB::delete('erp_412_events')->where('lot_id','IN',$this->lots)->execute();\DB::query(\Database::UPDATE,'ALTER TABLE erp_412_events ENABLE TRIGGER erp_412_events_immutable_trg')->execute();\DB::delete('erp_412_lots')->where('id','IN',$this->lots)->execute();}if($this->movements)\DB::delete('erp_401_movements')->where('id','IN',$this->movements)->execute();if($this->orders)\DB::delete('erp_402_orders')->where('id','IN',$this->orders)->execute();if($this->items){\DB::delete('erp_401_balances')->where('item_id','IN',$this->items)->execute();\DB::delete('erp_227_objects')->where('id','IN',$this->items)->execute();}}catch(\Throwable $e){}}
 protected function item($suffix){$type=(int)\DB::select('id')->from('erp_227_object_types')->where('code','=','component')->execute()->get('id');$r=\DB::insert('erp_227_objects',array('type_id','code','name','status','is_deleted'))->values(array($type,self::PREFIX.$suffix,self::PREFIX.$suffix,'active',FALSE))->execute();$this->items[]=(int)$r[0];return(int)$r[0];}
 protected function lot($item,$suffix,$extra=array()){$r=$this->s->create_lot($extra+array('item_id'=>$item,'lot_number'=>self::PREFIX.$suffix));$this->lots[]=(int)$r['id'];return$r;}
 protected function movement($type,$item,$qty,$warehouse=NULL,$to=NULL){$warehouse=$warehouse?:(int)\DB::select('id')->from('erp_401_warehouses')->order_by('id')->execute()->get('id');$r=\DB::insert('erp_401_movements',array('type','item_id','uom_code','warehouse_id','warehouse_to_id','qty','balance_before','balance_after','status','doc_type'))->values(array($type,$item,'pcs',$warehouse,$to,$qty,0,$qty,'posted','test412'))->execute();$this->movements[]=(int)$r[0];return(int)$r[0];}
 public function test_wms_receipt_event_automatically_creates_lot(){ $item=$this->item('EVENT');$warehouse=(int)\DB::select('id')->from('erp_401_warehouses')->order_by('id')->execute()->get('id');$movement=\Service_Erp401_Stock::instance()->receive($warehouse,$item,3,array('doc_type'=>'test412'));$this->movements[]=(int)$movement->id;$id=(int)\DB::select('id')->from('erp_412_lots')->where('source_type','=','erp401_movement')->where('source_id','=',(int)$movement->id)->execute()->get('id');$this->assertGreaterThan(0,$id);$this->lots[]=$id;$this->assertEquals(3,(float)$this->s->get($id)['qty_trace']);}
 public function test_receipt_is_idempotent_and_allocated_to_lot(){ $item=$this->item('IN');$m=$this->movement('receipt',$item,10);$a=$this->s->from_movement($m,array('lot_number'=>self::PREFIX.'AUTO'));$this->lots[]=(int)$a['id'];$b=$this->s->from_movement($m);$this->assertSame((int)$a['id'],(int)$b['id']);$this->assertEquals(10,(float)$this->s->get($a['id'])['qty_trace']);}
 public function test_allocations_cannot_exceed_movement_or_lot_balance(){ $item=$this->item('ALLOC');$lot=$this->lot($item,'ALLOC');$in=$this->movement('receipt',$item,5);$this->s->allocate($lot['id'],$in,'receipt',5);$out=$this->movement('issue',$item,6);$this->s->allocate($lot['id'],$out,'issue',4);$this->expectException(\Kohana_Exception::class);$this->s->allocate($lot['id'],$out,'issue',2);}
 public function test_quarantine_blocks_issue_and_quality_release_restores(){ $item=$this->item('QUALITY');$lot=$this->lot($item,'QUALITY');$in=$this->movement('receipt',$item,2);$this->s->allocate($lot['id'],$in,'receipt',2);$inspection=\DB::insert('erp_405_inspections',array('number','kind','source','item_id','item_name','qty','status'))->values(array(self::PREFIX.'QC','incoming','manual',$item,'Quality',2,'registered'))->execute()[0];$this->s->link_inspection($lot['id'],$inspection);$this->s->apply_quality_event('quarantined',array('id'=>$inspection));$out=$this->movement('issue',$item,1);try{$this->s->allocate($lot['id'],$out,'issue',1);$this->fail('Карантин обязан блокировать расход');}catch(\Kohana_Exception $e){$this->assertStringContainsString('заблокирована',$e->getMessage());}$this->s->apply_quality_event('released',array('id'=>$inspection));$this->s->allocate($lot['id'],$out,'issue',1);\DB::delete('erp_405_inspections')->where('id','=',$inspection)->execute();$this->assertSame('available',$this->s->get($lot['id'])['status']);}
 public function test_allocations_are_append_only(){ $item=$this->item('IMMUTABLE');$lot=$this->lot($item,'IMMUTABLE');$in=$this->movement('receipt',$item,1);$allocation=$this->s->allocate($lot['id'],$in,'receipt',1);$this->expectException(\Database_Exception::class);\DB::delete('erp_412_allocations')->where('id','=',$allocation['id'])->execute();}
 public function test_production_record_closes_wms_to_output_genealogy_idempotently(){
  $material=$this->item('MAT');$product=$this->item('PRODUCT');$warehouse=(int)\DB::select('id')->from('erp_401_warehouses')->order_by('id')->execute()->get('id');
  $order=\DB::insert('erp_402_orders',array('number','title','item_id','uom_code','qty','qty_done','status','warehouse_id','output_warehouse_id'))->values(array(self::PREFIX.'ORDER','Тестовый выпуск',$product,'pcs',2,2,'done',$warehouse,$warehouse))->execute()[0];$this->orders[]=(int)$order;
  \DB::insert('erp_402_order_items',array('order_id','line_no','item_id','name','uom_code','qty_per_unit','qty_total','qty_issued','warehouse_id','status'))->values(array($order,10,$material,'Материал','pcs',1.5,3,3,$warehouse,'issued'))->execute();
  $receipt=$this->movement('receipt',$material,3,$warehouse);$input=$this->s->from_movement($receipt,array('lot_number'=>self::PREFIX.'MAT-LOT'));$this->lots[]=(int)$input['id'];
  $issue=$this->movement('issue',$material,3,$warehouse);\DB::update('erp_401_movements')->set(array('doc_type'=>'erp402_order','doc_id'=>(int)$order))->where('id','=',$issue)->execute();
  $outputMovement=$this->movement('receipt',$product,2,$warehouse);\DB::update('erp_401_movements')->set(array('doc_type'=>'erp402_order','doc_id'=>(int)$order))->where('id','=',$outputMovement)->execute();$output=$this->s->from_movement($outputMovement,array('lot_number'=>self::PREFIX.'OUT-LOT'));$this->lots[]=(int)$output['id'];
  $first=$this->s->record_production($input['uuid'],$output['uuid'],$order,3);$second=$this->s->record_production($input['uuid'],$output['uuid'],$order,3);$this->assertFalse($first['replayed']);$this->assertTrue($second['replayed']);$this->assertEquals(0,(float)$this->s->get($input['id'])['qty_trace']);$this->assertCount(1,$this->s->genealogy($output['id'])['edges']);
 }
 public function test_label_view_uses_local_qr_asset_and_human_fallback(){ $lot=$this->lot($this->item('LABEL'),'LABEL');$html=(string)\View::factory('erp412/label')->set('lot',$lot)->set('scan_url','https://example.test/traceability/view/'.$lot['uuid']);$this->assertStringContainsString('assets/vendor/qrcode-generator/qrcode.js',$html);$this->assertStringContainsString($lot['lot_number'],$html);$this->assertStringContainsString($lot['uuid'],$html);$this->assertFileExists(DOCROOT.'assets/vendor/qrcode-generator/qrcode.js');$this->assertFileExists(DOCROOT.'assets/vendor/qrcode-generator/LICENSE.txt');}
 public function test_lot_card_cross_links_operational_objects(){ $view=file_get_contents(APPPATH.'modules/erp412_traceability/views/erp412/view.php');foreach(array('/traceability/view/','/production/orders/view/','/shopfloor/operations/view/','/quality/inspections/view/','/documents?ref_type=erp402_order') as $target)$this->assertStringContainsString($target,$view); }
 public function test_multilevel_genealogy_supports_impact_and_rejects_cycle(){ $a=$this->lot($this->item('A'),'A');$b=$this->lot($this->item('B'),'B');$c=$this->lot($this->item('C'),'C');$this->s->link(array('input_lot_id'=>$a['uuid'],'output_lot_id'=>$b['uuid'],'relation'=>'consume','qty_input'=>2));$this->s->link(array('input_lot_id'=>$b['uuid'],'output_lot_id'=>$c['uuid'],'relation'=>'rework','qty_input'=>1));$affected=$this->s->affected_outputs($a['uuid']);$this->assertCount(2,$affected);$graph=$this->s->genealogy($b['uuid']);$this->assertCount(3,$graph['nodes']);$this->expectException(\Kohana_Exception::class);$this->s->link(array('input_lot_id'=>$c['uuid'],'output_lot_id'=>$a['uuid'],'qty_input'=>1));}
 public function test_recall_is_audited_and_mcp_is_approval_gated(){ $lot=$this->lot($this->item('RECALL'),'RECALL');$this->s->transition($lot['uuid'],'recalled','Дефект поставщика');$events=(int)\DB::select(array(\DB::expr('count(*)'),'n'))->from('erp_412_events')->where('lot_id','=',$lot['id'])->execute()->get('n');$this->assertGreaterThanOrEqual(2,$events);$tools=\Service_Erp804_Registry::instance()->tools();foreach(array('traceability.lots','traceability.genealogy','traceability.affected_outputs','traceability.create_lot','traceability.link','traceability.production_record','traceability.status','traceability.recall') as $name)$this->assertArrayHasKey($name,$tools);$this->assertFalse($tools['traceability.genealogy']['mutating']);$this->assertTrue($tools['traceability.production_record']['mutating']);$this->assertTrue($tools['traceability.production_record']['approval']);$this->assertTrue($tools['traceability.production_record']['idempotent']);$this->assertTrue($tools['traceability.recall']['approval']);$this->assertTrue($tools['traceability.recall']['destructive']);}
}
